# =============================================================================
# LXC Sidecars Module
# =============================================================================
# Manages sidecar services for LXC containers:
#   - Backup: proxmox-backup-client with PBS integration
#   - Pulse Agent: Docker monitoring agent
#   - Arcane Agent: Remote container management agent
#   - Alloy Agent: Grafana Alloy for log/metric collection
#   - DIUN: Docker image update notifications (future)
# =============================================================================

# =============================================================================
# Backup Sidecar (PBS Client)
# =============================================================================

resource "ansible_navigator_run" "configure_backup" {
  count = var.backup != null && var.backup.enabled ? 1 : 0

  triggers = {
    container_id        = var.container_id
    container_ip        = var.container_ip
    namespace           = var.backup.namespace
    schedule            = var.backup.schedule
    retention           = var.backup.retention
    pre_backup_commands = jsonencode(var.backup.pre_backup_commands)
    include_paths       = jsonencode(var.backup.include_paths)
    exclude_paths       = jsonencode(var.backup.exclude_paths)
    pbs_server          = var.backup.pbs_server
    pbs_datastore       = var.backup.pbs_datastore
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host, not in container
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.proxmox_ssh_private_key_path)
    }]
  }

  playbook = templatefile("${path.module}/templates/configure-backup-playbook.yml.tftpl", {
    container_id        = var.container_id
    container_ip        = var.container_ip
    container_name      = var.container_name
    namespace           = var.backup.namespace
    schedule            = var.backup.schedule
    retention           = var.backup.retention
    pre_backup_commands = var.backup.pre_backup_commands
    include_paths       = var.backup.include_paths
    exclude_paths       = var.backup.exclude_paths
    pbs_server          = var.backup.pbs_server
    pbs_datastore       = var.backup.pbs_datastore
    pbs_user            = var.backup.pbs_user
    pbs_password_cmd    = var.backup.pbs_password_cmd
    ntfy_url            = var.backup.ntfy_url
    ntfy_priority       = var.backup.ntfy_priority
    ntfy_tags           = var.backup.ntfy_tags
    backup_script       = templatefile("${path.module}/templates/pbs-backup.sh.tftpl", {
      container_id        = var.container_id
      container_name      = var.container_name
      namespace           = var.backup.namespace
      schedule            = var.backup.schedule
      retention           = var.backup.retention
      pre_backup_commands = var.backup.pre_backup_commands
      include_paths       = var.backup.include_paths
      exclude_paths       = var.backup.exclude_paths
      ntfy_url            = var.backup.ntfy_url
      ntfy_priority       = var.backup.ntfy_priority
      ntfy_tags           = var.backup.ntfy_tags
      ntfy_user           = var.backup.ntfy_user
      ntfy_password       = var.backup.ntfy_password
      notify_on_success   = var.backup.notify_on_success
      notify_on_failure   = var.backup.notify_on_failure
    })
  })

  inventory = yamlencode({
    lxc = {
      hosts = {
        (var.container_name) = {
          ansible_host = var.container_ip
          ansible_user = "root"
        }
      }
    }
  })
}

# =============================================================================
# Container Management Agents (Pulse + Arcane + Alloy)
# =============================================================================
# Deploys all enabled agents in a single docker-compose file to avoid conflicts.
# All agents share the same compose file at /config/sidecars/docker-compose.yml

locals {
  # Check if any agent is enabled
  any_agent_enabled = (
    try(var.pulse_agent.enabled, false) ||
    try(var.arcane_agent.enabled, false) ||
    try(var.alloy_agent.enabled, false)
  )
}

resource "ansible_navigator_run" "configure_agents" {
  count = local.any_agent_enabled ? 1 : 0

  triggers = {
    container_id    = var.container_id
    container_ip    = var.container_ip
    pulse_enabled   = try(var.pulse_agent.enabled, false)
    pulse_url       = try(var.pulse_agent.pulse_url, "")
    pulse_token     = try(var.pulse_agent.enabled, false) ? sha256(var.pulse_agent.pulse_token) : ""
    arcane_enabled  = try(var.arcane_agent.enabled, false)
    manager_url     = try(var.arcane_agent.manager_url, "")
    bootstrap_token = try(var.arcane_agent.enabled, false) ? sha256(var.arcane_agent.bootstrap_token) : ""
    alloy_enabled   = try(var.alloy_agent.enabled, false)
    loki_url        = try(var.alloy_agent.loki_url, "")
    prometheus_url  = try(var.alloy_agent.prometheus_url, "")
    alloy_auth      = try(var.alloy_agent.enabled, false) ? sha256("${var.alloy_agent.username}:${var.alloy_agent.password}") : ""
  }

  execution_environment = {
    enabled = false
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.proxmox_ssh_private_key_path)
    }]
  }

  playbook = templatefile("${path.module}/templates/configure-agents-playbook.yml.tftpl", {
    container_id    = var.container_id
    container_ip    = var.container_ip
    container_name  = var.container_name
    pulse_enabled   = try(var.pulse_agent.enabled, false)
    pulse_url       = try(var.pulse_agent.pulse_url, "http://10.100.1.104:7655")
    pulse_token     = try(var.pulse_agent.pulse_token, "")
    arcane_enabled  = try(var.arcane_agent.enabled, false)
    manager_url     = try(var.arcane_agent.manager_url, "http://10.100.1.104:3552")
    bootstrap_token = try(var.arcane_agent.bootstrap_token, "")
    alloy_enabled   = try(var.alloy_agent.enabled, false)
    loki_url        = try(var.alloy_agent.loki_url, "https://loki-push.homelab.rambtech.dev")
    prometheus_url  = try(var.alloy_agent.prometheus_url, "https://prometheus-push.homelab.rambtech.dev")
    alloy_username  = try(var.alloy_agent.username, "")
    alloy_password  = try(var.alloy_agent.password, "")
  })

  inventory = yamlencode({
    lxc = {
      hosts = {
        (var.container_name) = {
          ansible_host = var.container_ip
          ansible_user = "root"
        }
      }
    }
  })
}

