# =============================================================================
# ntfy Template: PBS Backup
# =============================================================================
# Formats Proxmox Backup Server backup notifications
# Usage: POST to ntfy with ?template=pbs-backup
#
# Expected JSON payload:
# {
#   "status": "success|failure",
#   "container_name": "n8n",
#   "container_id": "502",
#   "namespace": "lxc-containers",
#   "duration": 120,
#   "backup_size": "1.2 GB",
#   "retention": 7,
#   "error_message": "..." (optional, for failures)
# }
# =============================================================================

# Title template
title: |
  {{- $status := .status -}}
  {{- $name := .container_name -}}
  {{- if eq $status "success" -}}
    💾 Backup Success: {{ $name }}
  {{- else if eq $status "failure" -}}
    🚨 Backup Failed: {{ $name }}
  {{- else -}}
    ⚠️ Backup: {{ $name }}
  {{- end -}}

# Message template
message: |
  {{- $status := .status -}}

  Container: {{ .container_name }} (LXC {{ .container_id }})
  Status: {{- if eq $status "success" }} SUCCESS ✓{{- else if eq $status "failure" }} FAILED ✗{{- else }} {{ $status | upper }}{{- end }}

  {{- if .namespace }}
  Namespace: {{ .namespace }}
  {{- end }}

  {{- if .duration }}
  Duration: {{ .duration }}s
  {{- end }}

  {{- if .backup_size }}
  Size: {{ .backup_size }}
  {{- end }}

  {{- if .retention }}
  Retention: {{ .retention }} backups
  {{- end }}

  {{- if .error_message }}
  Error: {{ .error_message }}
  {{- end }}

  {{- if .timestamp }}
  Completed: {{ .timestamp }}
  {{- end }}

