# =============================================================================
# LXC Sidecars Module Outputs
# =============================================================================

output "backup_enabled" {
  description = "Whether backup is enabled"
  value       = var.backup != null && var.backup.enabled
}

output "backup_namespace" {
  description = "PBS backup namespace"
  value       = var.backup != null ? var.backup.namespace : null
}

output "backup_schedule" {
  description = "Backup schedule"
  value       = var.backup != null ? var.backup.schedule : null
}

output "backup_timer_name" {
  description = "Systemd timer unit name"
  value       = var.backup != null && var.backup.enabled ? "pbs-backup-${var.container_id}.timer" : null
}

output "backup_log_path" {
  description = "Backup log file path"
  value       = var.backup != null && var.backup.enabled ? "/var/log/pbs-backups/${var.backup.namespace}.log" : null
}
